def clean():
    for f in glob.glob(WD+"/*"):
        os.remove(f)
def ref(args, data):
    return subprocess.run([EXE]+args, input=data, capture_output=True)
def ref_file(args, data):
    clean(); open(os.path.join(WD,"in.bin"),"wb").write(data)
    return subprocess.run([EXE]+args+["in.bin"], capture_output=True, cwd=WD)

data=b"hello world hello world this is test"
