import subprocess, base64
EXE="/workspace/executable"
def run(args, inp=b"hi"):
    return subprocess.run([EXE]+args, input=inp, capture_output=True)

comments=[
 b"", b"a", b"hello", b"hello world", b"\x00\x01\x02", b"A"*80, b"A"*81, b"\xff\xfe",
]
for c in comments:
    b64=base64.b64encode(c).decode()
    p=run(["-c","-C",b64], b"hi there hello")
    print(f"comment {c!r} b64={b64!r} rc={p.returncode} out={p.stdout.hex()} err={p.stderr}")
    q=run(["-d","-c"], p.stdout) if p.returncode==0 else None
    if q: print("  std dec", q.returncode, q.stdout, q.stderr)
    q2=run(["-d","-c","-C",b64], p.stdout) if p.returncode==0 else None
    if q2: print("  dec with same comment", q2.returncode, q2.stdout, q2.stderr)

# invalid base64
for b64 in ["!!!","aGVsbG8","aGVsbG8=","aGVs bG8=","====","QQ","QQ==","QQ==QQ==","-","_","aGVsbG8=\n","", "QUJD"*30]:
    p=run(["-c","-C",b64], b"hi")
    print(f"b64 invalid test {b64!r} rc={p.returncode} out={p.stdout[:100]} err={p.stderr[:500]}")
PY"}

