import subprocess, base64
EXE="/workspace/executable"
def run(args, inp=b"hi"):
    return subprocess.run([EXE]+args, input=inp, capture_output=True)

def summarize(cbytes):
    b64=base64.b64encode(cbytes).decode()
    p=run(["-c","-C",b64])
    print(f"len={len(cbytes)} b64={b64[:40]!r} rc={p.returncode} outlen={len(p.stdout) if p.returncode==0 else '-'} out={p.stdout.hex() if p.returncode==0 else p.stderr.decode().strip()} ")
for l in [0,1,2,3,4,5,6,7,8,79,80,81,82,100]:
    summarize(b"A"*l)
# decoding mismatch
def comp(comment,inp=b"hello data"):
    return run(["-c","-C",base64.b64encode(comment).decode()],inp).stdout
c1=comp(b"hello")
for dec_comment in [None, b"hello", b"hellx", b"hell", b"hello world", b""]:
    if dec_comment is None:
        args=["-d","-c"]
    else:
        args=["-d","-c","-C",base64.b64encode(dec_comment).decode()]
    q=run(args,c1)
    print("decode expected",dec_comment,"rc",q.returncode,"out",q.stdout,"err",q.stderr)
# decode a plain stream with comment expectation
plain=run(["-c"],b"hello data").stdout
for dec_comment in [b"hello", b""]:
    q=run(["-d","-c","-C",base64.b64encode(dec_comment).decode()],plain)
    print("plain decode expect",dec_comment,"rc",q.returncode,"out",q.stdout,"err",q.stderr)
# decode empty stream with comment etc
PY"}

