import pty, os, subprocess, time, select
def run(args, stdin_tty, stdout_tty, input_data=b"hello"):
    # create ptys as needed
    m_in=s_in=m_out=s_out=None
    if stdin_tty:
        m_in,s_in=pty.openpty()
    if stdout_tty:
        m_out,s_out=pty.openpty()
    p=subprocess.Popen(["/workspace/executable"]+args,
        stdin=s_in if stdin_tty else subprocess.PIPE,
        stdout=s_out if stdout_tty else subprocess.PIPE,
        stderr=subprocess.PIPE)
    if s_in is not None: os.close(s_in)
    if s_out is not None: os.close(s_out)
    if not stdin_tty:
        # communicate-ish but need read tty out
        try:
            out,err=p.communicate(input_data,timeout=2)
            # if stdout_tty, out is None
            if stdout_tty:
                # read from master
                os.set_blocking(m_out,False)
                data=b""
                try:
                    while True:
                        c=os.read(m_out,10000)
                        if not c: break
                        data+=c
                except Exception: pass
                out=data
        except subprocess.TimeoutExpired:
            p.kill(); out,err=p.communicate(); out=b"<timeout>"
    else:
        # stdin is tty: give it some time, then see if alive; if alive, close master (EOF) or kill
        time.sleep(0.6)
        if p.poll() is None:
            # try to read tty stdout if any before kill
            p.kill(); out_pipe,err=p.communicate(); out=b"<alive-killed>"
            if stdout_tty:
                os.set_blocking(m_out,False)
                data=b""
                try:
                    while True:
                        c=os.read(m_out,10000)
                        if not c: break
                        data+=c
                except Exception: pass
