  p_EncStream = (EncStreamFn)dlsym(e, "BrotliEncoderCompressStream");
  p_EncIsFinished = (EncIsFinishedFn)dlsym(e, "BrotliEncoderIsFinished");
  p_EncHasMore = (EncHasMoreFn)dlsym(e, "BrotliEncoderHasMoreOutput");
  p_DecCreate = (DecCreateFn)dlsym(d, "BrotliDecoderCreateInstance");
  p_DecDestroy = (DecDestroyFn)dlsym(d, "BrotliDecoderDestroyInstance");
  p_DecSetParam = (DecSetParamFn)dlsym(d, "BrotliDecoderSetParameter");
  p_DecStream = (DecStreamFn)dlsym(d, "BrotliDecoderDecompressStream");
  p_DecErrorCode = (DecErrorCodeFn)dlsym(d, "BrotliDecoderGetErrorCode");
  p_DecErrorString = (DecErrorStringFn)dlsym(d, "BrotliDecoderErrorString");
  return p_EncCreate && p_EncDestroy && p_EncSetParam && p_EncStream &&
         p_DecCreate && p_DecDestroy && p_DecSetParam && p_DecStream;
}

/* ---------------- small utilities ---------------- */
typedef struct {
  uint8_t *data;
  size_t len;
  size_t cap;
} Buffer;

static bool BufferReserve(Buffer *b, size_t extra) {
  if (b->len + extra <= b->cap) return true;
  size_t need = b->len + extra;
  size_t nc = b->cap ? b->cap : 256;
  while (nc < need) {
    if (nc > ((size_t)-1) / 2) { nc = need; break; }
    nc *= 2;
  }
  uint8_t *np = (uint8_t *)realloc(b->data, nc);
  if (!np) return false;
  b->data = np;
  b->cap = nc;
  return true;
}
static bool BufferAppend(Buffer *b, const void *src, size_t n) {
  if (!BufferReserve(b, n)) return false;
  if (n) memcpy(b->data + b->len, src, n);
  b->len += n;
  return true;
}
static void BufferFree(Buffer *b) {
  free(b->data);
  b->data = NULL; b->len = b->cap = 0;
}
static char *DupStr(const char *s) {
  size_t n = strlen(s) + 1;
  char *p = (char *)malloc(n);
  if (p) memcpy(p, s, n);
  return p;
}

/* Bit writer (stream order: first bit is LSB of first byte). */
typedef struct {
  Buffer buf;
  size_t bit_len;
} BitWriter;
static bool BWAppendBit(BitWriter *bw, int bit) {
  size_t byteidx = bw->bit_len / 8;
  if (byteidx == bw->buf.len) {
    uint8_t zero = 0;
    if (!BufferAppend(&bw->buf, &zero, 1)) return false;
  }
  if (bit) bw->buf.data[byteidx] |= (uint8_t)(1u << (bw->bit_len % 8));
  bw->bit_len++;
  return true;
}
static bool BWAppendValue(BitWriter *bw, uint32_t value, int count) {
  for (int i = 0; i < count; i++) if (!BWAppendBit(bw, (int)((value >> i) & 1u))) return false;
  return true;
}
static bool BWAppendSeq(BitWriter *bw, const char *seq) {
  for (; *seq; seq++) if (!BWAppendBit(bw, *seq == '1')) return false;
  return true;
}
static bool BWAlign(BitWriter *bw) {
  while (bw->bit_len % 8) if (!BWAppendBit(bw, 0)) return false;
  return true;
}
static bool BWAppendBytes(BitWriter *bw, const uint8_t *src, size_t n) {
  /* must be byte aligned */
  if (!BWAlign(bw)) return false;
  if (!BufferAppend(&bw->buf, src, n)) return false;
  bw->bit_len += n * 8;
  return true;
}

typedef struct {
  const uint8_t *data;
  size_t len;
  size_t bitpos;
} BitReader;
static bool BRRead(BitReader *br, int count, uint32_t *out) {
  uint32_t v = 0;
  for (int i = 0; i < count; i++) {
    size_t p = br->bitpos + (size_t)i;
    if (p / 8 >= br->len) return false;
    int bit = (br->data[p / 8] >> (p % 8)) & 1;
    if (bit) v |= (uint32_t)1 << i;
  }
  br->bitpos += (size_t)count;
  if (out) *out = v;
  return true;
}
static bool BRReadBit(BitReader *br, uint32_t *out) { return BRRead(br, 1, out); }

