static bool ParseCanonicalUnsigned(const char *s, long *out) {
  if (!s || !*s) return false;
  if (s[0] == '0') {
    if (s[1] != '\0') return false;
    *out = 0; return true;
  }
  if (s[0] < '1' || s[0] > '9') return false;
  long v = 0;
  for (const char *p = s; *p; p++) {
    if (*p < '0' || *p > '9') return false;
    if (v < 1000000) v = v * 10 + (*p - '0');
    else v = 1000001;
  }
  *out = v; return true;
}
static void DoQualityParam(const char *value) {
  if (g_quality_set) ParseFail("quality already set\n");
  long v;
  if (!ParseCanonicalUnsigned(value, &v) || v < 0 || v > 11) {
    ParseFail("error parsing quality value [%s]\n", value);
  }
  g_quality_set = true; g_quality = (int)v;
}
static void DoLgwinParam(const char *value, bool large) {
  if (g_lgwin_set) ParseFail("lgwin parameter already set\n");
  long v;
  long mx = large ? 30 : 24;
  if (!ParseCanonicalUnsigned(value, &v)) {
    ParseFail("error parsing lgwin value [%s]\n", value);
  }
  if (v >= 1 && v < 10) {
    ParseFail("lgwin parameter (%ld) smaller than the minimum (10)\n", v);
  }
  if (!(v == 0 || (v >= 10 && v <= mx))) {
    ParseFail("error parsing lgwin value [%s]\n", value);
  }
  g_lgwin_set = true; g_lgwin = (int)v; g_large_window_arg = large;
}
static int Base64Val(int c) {
  if (c >= 'A' && c <= 'Z') return c - 'A';
  if (c >= 'a' && c <= 'z') return c - 'a' + 26;
  if (c >= '0' && c <= '9') return c - '0' + 52;
  if (c == '+' || c == '-') return 62;
  if (c == '/' || c == '_') return 63;
  return -1;
}
static bool DecodeBase64(const char *s, uint8_t **out_data, size_t *out_len) {
  size_t cap = strlen(s) + 4;
  int *vals = (int *)malloc(cap * sizeof(int));
  uint8_t *out = (uint8_t *)malloc(cap + 4);
  if (!vals || !out) { free(vals); free(out); return false; }
  size_t nv = 0;
  int pads = 0;
  bool after_pad = false;
  for (const unsigned char *p = (const unsigned char *)s; *p; p++) {
    int c = *p;
    if (c == ' ' || c == '\t' || c == '\r' || c == '\n') continue;
    if (c == '=') {
      pads++;
      if (pads > 2) { free(vals); free(out); return false; }
      after_pad = true; continue;
    }
    if (after_pad) { free(vals); free(out); return false; }
    int v = Base64Val(c);
    if (v < 0) { free(vals); free(out); return false; }
    vals[nv++] = v;
  }
  size_t olen = 0;
  for (size_t i = 0; i < nv; ) {
    size_t rem = nv - i;
    if (rem == 1) break;
    int v0 = vals[i], v1 = vals[i + 1];
    out[olen++] = (uint8_t)((v0 << 2) | (v1 >> 4));
    if (rem >= 3) {
      int v2 = vals[i + 2];
      out[olen++] = (uint8_t)(((v1 & 15) << 4) | (v2 >> 2));
      if (rem >= 4) {
        int v3 = vals[i + 3];
        out[olen++] = (uint8_t)(((v2 & 3) << 6) | v3);
      }
    }
    i += (rem >= 4 ? 4 : rem);
  }
  free(vals);
  if (olen > 80) { free(out); return false; }
  *out_data = out; *out_len = olen;
  return true;
}
static void DoCommentParam(const char *value) {
  if (g_comment_set) ParseFail("comment already set\n");
  uint8_t *data = NULL; size_t len = 0;
  if (!DecodeBase64(value, &data, &len)) {
    ParseFail("invalid base64-encoded comment\n");
  }
  g_comment_set = true; g_comment = data; g_comment_len = len;
}
static void DoDictParam(const char *value) {
  if (g_dict_set) ParseFail("dictionary path already set\n");
  g_dict_set = true; g_dict_path = DupStr(value);
}
static void DoSuffixParam(const char *value) {
  if (g_suffix_set) ParseFail("suffix already set\n");
  g_suffix_set = true; free(g_suffix); g_suffix = DupStr(value);
}
static void DoOutputParam(const char *value, const char *display) {
  if (g_stdout_set) ParseFail("write to standard output already set (%s)\n", display);
  free(g_output_name); g_output_name = DupStr(value); g_output_set = true;
}

/* dispatcher for parameter canonical names */
static void DoLongParam(const char *canon, const char *value) {
  if (strcmp(canon, "comment") == 0) DoCommentParam(value);
  else if (strcmp(canon, "dictionary") == 0) DoDictParam(value);
  else if (strcmp(canon, "lgwin") == 0) DoLgwinParam(value, false);
  else if (strcmp(canon, "large_window") == 0) DoLgwinParam(value, true);
  else if (strcmp(canon, "output") == 0) DoOutputParam(value, "--output");
  else if (strcmp(canon, "quality") == 0) DoQualityParam(value);
  else if (strcmp(canon, "suffix") == 0) DoSuffixParam(value);
}

/* ---------------- parsing ---------------- */
static void ParseArgs(int argc, char **argv) {
  bool only_files = false;
  static const char *long_params[] = {
    "comment", "lgwin", "large_window", "dictionary", "output", "quality", "suffix", NULL
  };
  for (int i = 1; i < argc; i++) {
    char *arg = argv[i];
    if (arg[0] == '\0') continue;
    if (only_files) { AddInput(arg); continue; }
    if (strcmp(arg, "--") == 0) { only_files = true; continue; }
    if (arg[0] != '-' || arg[1] == '\0') { AddInput(arg); continue; }
    if (arg[1] == '-') {
      const char *token = arg + 2;
      /* exact flag options */
      if (strcmp(token, "help") == 0) { PrintUsage(stderr); exit(0); }
      if (strcmp(token, "version") == 0) { printf("brotli 1.2.0\n"); exit(0); }
      if (strcmp(token, "stdout") == 0) { SetStdout(); continue; }
      if (strcmp(token, "decompress") == 0) { SetCommand(MODE_DECOMPRESS, "--decompress"); continue; }
      if (strcmp(token, "test") == 0) { SetCommand(MODE_TEST, "--test"); continue; }
      if (strcmp(token, "force") == 0) { SetForce(); continue; }
      if (strcmp(token, "rm") == 0) { SetRmKeep(true); continue; }
      if (strcmp(token, "keep") == 0) { SetRmKeep(false); continue; }
      if (strcmp(token, "squash") == 0) { SetSquash(); continue; }
      if (strcmp(token, "no-copy-stat") == 0) { SetNoCopy(); continue; }
      if (strcmp(token, "verbose") == 0) { SetVerbose(); continue; }
      if (strcmp(token, "concatenated") == 0) { SetConcat(); continue; }
      if (strcmp(token, "best") == 0) { SetBest(); continue; }
      /* parameterised long options */
      const char *eq = strchr(token, '=');
      if (!eq || eq[1] == '\0') {
        ParseFail("must pass the parameter as %s=value\n", arg);
      }
      size_t name_len = (size_t)(eq - token);
      const char *value = eq + 1;
      const char *matched = NULL;
      for (int k = 0; long_params[k]; k++) {
        if (strncmp(long_params[k], token, name_len) == 0) { matched = long_params[k]; break; }
      }
      if (!matched) ParseFail("invalid parameter: [%s]\n", token);
      DoLongParam(matched, value);
      continue;
    }
    /* short options, possibly coalesced */
    size_t alen = strlen(arg);
    for (size_t pos = 1; pos < alen; pos++) {
      char c = arg[pos];
      if (c >= '0' && c <= '9') { SetQualityValue(c - '0'); continue; }
      switch (c) {
        case 'c': SetStdout(); break;
        case 'd': SetCommand(MODE_DECOMPRESS, "-d"); break;
        case 't': SetCommand(MODE_TEST, "-t"); break;
        case 'f': SetForce(); break;
        case 'j': SetRmKeep(true); break;
        case 'k': SetRmKeep(false); break;
        case 's': SetSquash(); break;
        case 'n': SetNoCopy(); break;
        case 'v': SetVerbose(); break;
        case 'K': SetConcat(); break;
        case 'Z': SetBest(); break;
        case 'h': PrintUsage(stderr); exit(0); break;
        case 'V': printf("brotli 1.2.0\n"); exit(0); break;
        case 'q': case 'w': case 'C': case 'D': case 'S': case 'o': {
          if (pos != alen - 1) ParseFail("expected parameter for argument -%c\n", c);
          if (i + 1 >= argc || argv[i + 1][0] == '\0') ParseFail("expected parameter for argument -%c\n", c);
          const char *value = argv[++i];
          if (c == 'q') DoQualityParam(value);
          else if (c == 'w') DoLgwinParam(value, false);
          else if (c == 'C') DoCommentParam(value);
          else if (c == 'D') DoDictParam(value);
          else if (c == 'S') DoSuffixParam(value);
          else if (c == 'o') DoOutputParam(value, "-o");
          break;
        }
        default: ParseFail("invalid argument -%c\n", c); break;
      }
    }
  }
}

static bool ValidateParams(void) {
  bool invalid = false;
  if (g_squash && g_stdout_set) invalid = true;
  if (g_concat && g_mode != MODE_DECOMPRESS) invalid = true;
  if (g_concat && g_comment_len > 0) invalid = true;
  if (g_mode == MODE_TEST && (g_stdout_set || g_output_set || g_concat)) invalid = true;
  if (g_stdout_set && g_inputs_len > 1) invalid = true;
  if (g_suffix && (strchr(g_suffix, '/') || strchr(g_suffix, '\\'))) invalid = true;
  if (invalid) { PrintUsage(stdout); return false; }
  return true;
}

static bool LoadDictionary(void) {
  if (!g_dict_set) return true;
  FILE *f = fopen(g_dict_path, "rb");
  if (!f) {
    fprintf(stderr, "failed to open dictionary file [%s]: %s\n", g_dict_path, strerror(errno));
    return false;
  }
  size_t size = 0;
  if (fseek(f, 0, SEEK_END) == 0) {
    long long sz = (long long)ftello(f);
    if (sz > 0) size = (size_t)sz;
  }
  uint8_t *data = NULL;
  if (size > 0) {
    data = (uint8_t *)calloc(size, 1);
    if (data) {
      (void)fseek(f, 0, SEEK_SET);
      (void)fread(data, 1, size, f);
    } else size = 0;
  }
  fclose(f);
  g_dictionary = data;
  g_dictionary_len = size;
  return true;
}

/* ---------------- formatting ---------------- */
static void FormatSize(uint64_t size, char *buf, size_t bufsz) {
  if (size < 1024) {
    snprintf(buf, bufsz, "%" PRIu64 " B", size);
    return;
  }
  static const char *units[] = {"KiB", "MiB", "GiB", "TiB", "PiB", "EiB"};
  double v = (double)size;
  int idx = -1;
  while (v >= 1024.0 && idx < 5) { v /= 1024.0; idx++; }
  if (idx < 0) idx = 0;
  snprintf(buf, bufsz, "%.3f %s", v, units[idx]);
}

static bool WriteOutput(FILE *out, const uint8_t *data, size_t len, const char *display, uint64_t *counter) {
  if (len == 0) return true;
  errno = 0;
  size_t written = fwrite(data, 1, len, out);
  if (written != len) {
    int e = errno;
    fprintf(stderr, "failed to write output [%s]: %s\n", display, strerror(e ? e : EIO));
    return false;
  }
  if (counter) *counter += len;
  return true;
}

/* ---------------- window / comment parsing ---------------- */
static bool ParseWindowBits(const uint8_t *data, size_t len, size_t *out_bits, bool *out_large) {
  BitReader br; br.data = data; br.len = len; br.bitpos = 0;
  uint32_t first;
  if (!BRReadBit(&br, &first)) return false;
  if (out_large) *out_large = false;
  if (first == 0) { *out_bits = 1; return true; }
  uint32_t n1;
  if (!BRRead(&br, 3, &n1)) return false;
  if (n1 != 0) { *out_bits = 4; return true; }
  uint32_t n2;
  if (!BRRead(&br, 3, &n2)) return false;
  if (n2 == 1) {
    /* reserved / large-window escape: total header is 14 bits */
    *out_bits = 14;
    if (out_large) *out_large = true;
    return true;
  }
  *out_bits = 7;
  return true;
}

/* returns 0=unknown 1=absent 2=match 3=mismatch */
static int CheckFirstMetadata(const uint8_t *data, size_t len) {
  size_t wbits = 0; bool large = false;
  (void)large;
  if (!ParseWindowBits(data, len, &wbits, &large)) return 0;
  BitReader br; br.data = data; br.len = len; br.bitpos = wbits;
  uint32_t islast;
  if (!BRReadBit(&br, &islast)) return 0;
  if (islast) return 1;
  uint32_t mnib;
  if (!BRRead(&br, 2, &mnib)) return 0;
  if (mnib != 3) return 1;
  uint32_t reserved;
  if (!BRReadBit(&br, &reserved)) return 0;
  if (reserved != 0) return 0;
  uint32_t skipbytes;
  if (!BRRead(&br, 2, &skipbytes)) return 0;
  uint64_t meta_len = 0;
  if (skipbytes == 0) {
    meta_len = 0;
  } else {
    uint32_t v = 0;
    if (!BRRead(&br, (int)(8 * skipbytes), &v)) return 0;
    meta_len = (uint64_t)v + 1;
  }
  /* align to byte */
  br.bitpos = (br.bitpos + 7) & ~((size_t)7);
  size_t bytepos = br.bitpos / 8;
  if (bytepos > len) return 0;
  size_t available = len - bytepos;
  if (meta_len > available) {
    /* truncated inside the metadata block */
    if (meta_len != (uint64_t)g_comment_len) return 3;
    size_t cmp = available < g_comment_len ? available : g_comment_len;
    if (cmp && memcmp(data + bytepos, g_comment, cmp) != 0) return 3;
    return 0;
  }
  if (meta_len == (uint64_t)g_comment_len && (meta_len == 0 || memcmp(data + bytepos, g_comment, (size_t)meta_len) == 0)) return 2;
  return 3;
}

/* ---------------- encoder ---------------- */
static int EffectiveWindow(bool is_stdin, bool have_size, uint64_t file_size, bool *out_large_effective) {
  int w;
  bool large_effective = false;
  if (g_lgwin != 0) {
    w = g_lgwin;
  } else {
    if (is_stdin || !have_size) {
      w = 24;
    } else {
      w = 24;
      for (int cand = 10; cand <= 24; cand++) {
        uint64_t cap = ((uint64_t)1 << cand) - 16;
        if (cap >= file_size) { w = cand; break; }
      }
    }
  }
  if (g_large_window_arg && w > 24) large_effective = true;
  /* Also a window explicitly above 24 can only come via --large_window. */
  if (w > 24) large_effective = true;
  if (out_large_effective) *out_large_effective = large_effective;
  return w;
}

static bool PatchOneByteMetadata(Buffer *meta, int window, bool large_effective) {
  if (g_comment_len != 1) return true;
  int k;
  if (large_effective) k = 14;
  else if (window == 16) k = 1;
  else if (window >= 18 && window <= 24) k = 4;
  else k = 7;
  size_t old_header_bytes = (size_t)(k + 6 + 7) / 8;
  if (meta->len != old_header_bytes + 1) return true; /* leave as-is */
  uint8_t comment_byte = meta->data[old_header_bytes];
  BitWriter bw; memset(&bw, 0, sizeof(bw));
  for (int i = 0; i < k + 6; i++) {
    size_t p = (size_t)i;
    int bit = (meta->data[p / 8] >> (p % 8)) & 1;
    if (i == k + 4) bit = 1;
    if (!BWAppendBit(&bw, bit)) return false;
  }
  if (!BWAppendValue(&bw, 0, 8)) return false;
  if (!BWAlign(&bw)) return false;
  if (!BufferAppend(&bw.buf, &comment_byte, 1)) return false;
  BufferFree(meta);
  *meta = bw.buf;
  return true;
}

static bool EmitMetadata(void *state, Buffer *collected) {
  const uint8_t *next_in = g_comment;
  size_t avail_in = g_comment_len;
  while (true) {
    uint8_t outbuf[8192];
    size_t avail_out = sizeof(outbuf);
    uint8_t *next_out = outbuf;
    size_t total = 0;
    int ok = p_EncStream(state, 3, &avail_in, &next_in, &avail_out, &next_out, &total);
    if (!ok) return false;
    size_t produced = sizeof(outbuf) - avail_out;
    if (produced && !BufferAppend(collected, outbuf, produced)) return false;
    if (avail_in == 0 && !p_EncHasMore(state)) break;
    if (produced == 0 && avail_in == 0) break;
  }
  return true;
}

/* store an uncompressed data stream (used only with a non-empty dictionary) */
static bool BWWindowBits(BitWriter *bw, int window, bool large_effective) {
  if (large_effective) {
    const char *seq = NULL;
    switch (window) {
      case 25: seq = "10001000100110"; break;
      case 26: seq = "10001000010110"; break;
      case 27: seq = "10001000110110"; break;
      case 28: seq = "10001000001110"; break;
      case 29: seq = "10001000101110"; break;
      case 30: seq = "10001000011110"; break;
      default: seq = "10001000100110"; break;
    }
    return BWAppendSeq(bw, seq);
  }
  if (window == 16) return BWAppendSeq(bw, "0");
  if (window == 17) return BWAppendSeq(bw, "1000000");
  if (window >= 18 && window <= 24) {
    if (!BWAppendBit(bw, 1)) return false;
    return BWAppendValue(bw, (uint32_t)(window - 17), 3);
  }
  /* 10..15 */
  if (!BWAppendSeq(bw, "1000")) return false;
  return BWAppendValue(bw, (uint32_t)(window - 8), 3);
}
static bool BWMetadataBlock(BitWriter *bw, const uint8_t *data, size_t len) {
  if (!BWAppendBit(bw, 0)) return false;
  if (!BWAppendValue(bw, 3, 2)) return false;
  if (!BWAppendBit(bw, 0)) return false;
  if (!BWAppendValue(bw, 1, 2)) return false;
  if (!BWAppendValue(bw, (uint32_t)(len - 1), 8)) return false;
  if (!BWAppendBytes(bw, data, len)) return false;
  return true;
}
static bool BWStoredBlock(BitWriter *bw, const uint8_t *data, size_t len) {
  if (!BWAppendBit(bw, 0)) return false;
  int code, nibbles;
  uint32_t v = (uint32_t)(len - 1);
  if (len - 1 < ((size_t)1 << 16)) { code = 0; nibbles = 4; }
  else if (len - 1 < ((size_t)1 << 20)) { code = 1; nibbles = 5; }
  else { code = 2; nibbles = 6; }
  if (!BWAppendValue(bw, (uint32_t)code, 2)) return false;
  for (int i = 0; i < nibbles; i++) {
    if (!BWAppendValue(bw, (v >> (4 * i)) & 15u, 4)) return false;
  }
  if (!BWAppendBit(bw, 1)) return false;
  if (!BWAppendBytes(bw, data, len)) return false;
  return true;
}

typedef struct {
  bool success;
  uint64_t in_size;
  uint64_t out_size;
  int read_errno;
} CompressResult;

static CompressResult DoCompress(FILE *in, FILE *out, const char *in_display, const char *out_display,
                                 bool is_stdin, bool have_size, uint64_t file_size) {
  CompressResult res; memset(&res, 0, sizeof(res));
  bool large_effective = false;
  int window = EffectiveWindow(is_stdin, have_size, file_size, &large_effective);

  /* dictionary path: emit a stored stream (decodable with/without dictionary) */
  if (g_dictionary_len > 0) {
    Buffer input; memset(&input, 0, sizeof(input));
    uint8_t chunk[524288];
    while (true) {
      errno = 0;
      size_t n = fread(chunk, 1, sizeof(chunk), in);
      if (n) { if (!BufferAppend(&input, chunk, n)) { BufferFree(&input); return res; } }
      if (n == 0) {
        if (ferror(in)) { res.read_errno = errno ? errno : EIO; BufferFree(&input); return res; }
        break;
      }
      if (n < sizeof(chunk)) {
        if (ferror(in)) { res.read_errno = errno ? errno : EIO; BufferFree(&input); return res; }
        if (feof(in)) break;
      }
    }
    res.in_size = input.len;
    BitWriter bw; memset(&bw, 0, sizeof(bw));
    bool ok = BWWindowBits(&bw, window, large_effective);
    if (ok && g_comment_len > 0) ok = BWMetadataBlock(&bw, g_comment, g_comment_len);
    if (ok) {
      if (input.len == 0) {
        ok = BWAppendBit(&bw, 1) && BWAppendBit(&bw, 1) && BWAlign(&bw);
      } else {
        size_t pos = 0;
        while (ok && pos < input.len) {
          size_t clen = input.len - pos;
          if (clen > 1000000) clen = 1000000;
          ok = BWStoredBlock(&bw, input.data + pos, clen);
          pos += clen;
        }
        if (ok) ok = BWAppendBit(&bw, 1) && BWAppendBit(&bw, 1) && BWAlign(&bw);
      }
    }
    BufferFree(&input);
    if (!ok) { BufferFree(&bw.buf); return res; }
    if (!WriteOutput(out, bw.buf.data, bw.buf.len, out_display, &res.out_size)) { BufferFree(&bw.buf); return res; }
    BufferFree(&bw.buf);
    res.success = true;
    return res;
  }

  void *state = p_EncCreate(NULL, NULL, NULL);
  if (!state) return res;
  p_EncSetParam(state, 1, (uint32_t)g_quality);
  p_EncSetParam(state, 2, (uint32_t)window);
  if (large_effective) p_EncSetParam(state, 6, 1);

  uint8_t *inbuf = (uint8_t *)malloc(524288);
  if (!inbuf) { p_EncDestroy(state); return res; }

  /* read first chunk before emitting any output */
  errno = 0;
  size_t chunk_len = fread(inbuf, 1, 524288, in);
  int first_errno = errno;
  if (chunk_len < 524288 && ferror(in)) {
    fprintf(stderr, "failed to read input [%s]: %s\n", in_display, strerror(first_errno ? first_errno : EIO));
    free(inbuf); p_EncDestroy(state); return res;
  }
  bool chunk_is_last = false;
  if (chunk_len < 524288 && feof(in)) chunk_is_last = true;

  if (g_comment_len > 0) {
    Buffer meta; memset(&meta, 0, sizeof(meta));
    if (!EmitMetadata(state, &meta)) { BufferFree(&meta); free(inbuf); p_EncDestroy(state); return res; }
    (void)PatchOneByteMetadata(&meta, window, large_effective);
    if (!WriteOutput(out, meta.data, meta.len, out_display, &res.out_size)) {
      BufferFree(&meta); free(inbuf); p_EncDestroy(state); return res;
    }
    BufferFree(&meta);
  }

  while (true) {
    res.in_size += chunk_len;
    int op = chunk_is_last ? 2 : 0;
    const uint8_t *next_in = inbuf;
    size_t avail_in = chunk_len;
    bool stream_failed = false;
    while (true) {
      uint8_t outbuf[8192];
      size_t avail_out = sizeof(outbuf);
      uint8_t *next_out = outbuf;
      size_t total = 0;
      int ok = p_EncStream(state, op, &avail_in, &next_in, &avail_out, &next_out, &total);
      if (!ok) { stream_failed = true; break; }
      size_t produced = sizeof(outbuf) - avail_out;
      if (produced && !WriteOutput(out, outbuf, produced, out_display, &res.out_size)) { stream_failed = true; break; }
      if (op == 2 && p_EncIsFinished(state)) break;
      if (avail_in == 0 && !p_EncHasMore(state) && op != 2) break;
      if (op == 2 && avail_in == 0 && !p_EncHasMore(state) && produced == 0) {
        if (p_EncIsFinished(state)) break;
      }
    }
    if (stream_failed) { free(inbuf); p_EncDestroy(state); return res; }
    if (chunk_is_last) break;
    errno = 0;
    chunk_len = fread(inbuf, 1, 524288, in);
    int e = errno;
    if (chunk_len < 524288 && ferror(in)) {
      fprintf(stderr, "failed to read input [%s]: %s\n", in_display, strerror(e ? e : EIO));
      free(inbuf); p_EncDestroy(state); return res;
    }
    chunk_is_last = (chunk_len < 524288 && feof(in));
  }
  free(inbuf);
  p_EncDestroy(state);
  res.success = true;
  return res;
}

/* ---------------- decoder ---------------- */
typedef struct {
  bool success;
  uint64_t in_size;
  uint64_t out_size;
  bool comment_absent;
  /* failure info */
  int fail_kind; /* 0 none, 1 decoder error, 2 truncated, 3 extra, 4 comment mismatch, 5 other (message already printed) */
  int error_code;
} DecompressResult;

static const char *DecoderReason(int code, char *buf, size_t bufsz) {
  const char *s = NULL;
  if (p_DecErrorString) s = p_DecErrorString(code);
  if (code <= -1 && code >= -16 && s) {
    snprintf(buf, bufsz, "FORMAT_%s (%d)", s, code);
    return buf;
  }
  if (s) {
    snprintf(buf, bufsz, "%s (%d)", s, code);
    return buf;
  }
  snprintf(buf, bufsz, "(%d)", code);
  return buf;
}

/* Build a synthetic stream: window bits + stored dictionary + original bits.
   Returns NULL on failure. */
static Buffer BuildSynthetic(const uint8_t *data, size_t len) {
  Buffer out; memset(&out, 0, sizeof(out));
  size_t wbits = 0; bool large = false;
  if (!ParseWindowBits(data, len, &wbits, &large)) return out;
  (void)large;
  BitWriter bw; memset(&bw, 0, sizeof(bw));
  /* append original window bits */
  for (size_t i = 0; i < wbits; i++) {
    int bit = (data[i / 8] >> (i % 8)) & 1;
    if (!BWAppendBit(&bw, bit)) { BufferFree(&bw.buf); return out; }
  }
  /* dictionary as stored blocks */
  size_t pos = 0;
  while (pos < g_dictionary_len) {
    size_t clen = g_dictionary_len - pos;
    if (clen > 1000000) clen = 1000000;
    if (!BWStoredBlock(&bw, g_dictionary + pos, clen)) { BufferFree(&bw.buf); return out; }
    pos += clen;
  }
  if (!BWAlign(&bw)) { BufferFree(&bw.buf); return out; }
  /* append original payload bits from wbits onward, packed */
  size_t total_bits = len * 8;
  if (wbits < total_bits) {
    size_t payload_bits = total_bits - wbits;
    size_t payload_bytes = (payload_bits + 7) / 8;
    size_t src_byte = wbits / 8;
    int src_off = (int)(wbits % 8);
    for (size_t i = 0; i < payload_bytes; i++) {
      size_t idx = src_byte + i;
      uint8_t b = 0;
      if (src_off == 0) {
        b = data[idx];
      } else {
        int lo = 0, hi = 0;
        if (idx < len) lo = data[idx] >> src_off;
        if (idx + 1 < len) hi = data[idx + 1] << (8 - src_off);
        b = (uint8_t)(lo | hi);
      }
      if (i == payload_bytes - 1 && payload_bits % 8) {
        b &= (uint8_t)((1u << (payload_bits % 8)) - 1u);
      }
      if (!BufferAppend(&bw.buf, &b, 1)) { BufferFree(&bw.buf); return out; }
      bw.bit_len += 8;
      if (bw.bit_len > ((bw.buf.len) * 8)) bw.bit_len = bw.buf.len * 8; /* not critical */
    }
    /* correct bit_len: we aligned before plus payload bytes */
    bw.bit_len = bw.buf.len * 8;
  }
  out = bw.buf;
  return out;
}

/* Decode a single stream from `data` into spool, skipping dict_len at start if
   skip_dict is set (for synthetic buffers). */
typedef struct {
  int status; /* 0 success, 1 error, 2 truncated */
  int error_code;
  size_t consumed;
  uint64_t produced; /* excluding skipped */
} OneStreamResult;

static OneStreamResult DecodeOne(const uint8_t *data, size_t len, FILE *spool, uint64_t skip_prefix) {
  OneStreamResult r; memset(&r, 0, sizeof(r));
  void *state = p_DecCreate(NULL, NULL, NULL);
  if (!state) { r.status = 1; r.error_code = 0; return r; }
  if (p_DecSetParam) p_DecSetParam(state, 1, 1);
  const uint8_t *next_in = data;
  size_t avail_in = len;
  uint64_t skip = skip_prefix;
  while (true) {
    uint8_t outbuf[8192];
    size_t avail_out = sizeof(outbuf);
    uint8_t *next_out = outbuf;
    size_t total = 0;
    int ret = p_DecStream(state, &avail_in, &next_in, &avail_out, &next_out, &total);
    size_t produced = sizeof(outbuf) - avail_out;
    if (produced) {
      const uint8_t *p = outbuf;
      size_t n = produced;
      if (skip >= n) { skip -= n; n = 0; }
      else if (skip > 0) { p += skip; n -= (size_t)skip; skip = 0; }
      if (n) {
        if (spool) (void)fwrite(p, 1, n, spool);
        r.produced += n;
      }
    }
    if (ret == 1) { r.status = 0; break; }
    if (ret == 0) {
      r.status = 1;
      r.error_code = p_DecErrorCode ? p_DecErrorCode(state) : 0;
      break;
    }
    if (ret == 2) { r.status = 2; break; }
    /* ret == 3 need more output: loop */
    if (ret != 3) { r.status = 1; r.error_code = p_DecErrorCode ? p_DecErrorCode(state) : 0; break; }
  }
  r.consumed = (size_t)(next_in - data);
  /* Brotli's decoder may leave next_in at a position such that consumed is
     correct for concatenated use. */
  p_DecDestroy(state);
  return r;
}

static bool CopySpoolToOutput(FILE *spool, FILE *out, const char *out_display, uint64_t *counter) {
  (void)fflush(spool);
  (void)fseek(spool, 0, SEEK_SET);
  uint8_t buf[8192];
  size_t n;
  while ((n = fread(buf, 1, sizeof(buf), spool)) > 0) {
    if (!WriteOutput(out, buf, n, out_display, counter)) return false;
  }
  return true;
}

static DecompressResult DoDecompress(FILE *in, FILE *out, const char *in_display, const char *out_display) {
  DecompressResult res; memset(&res, 0, sizeof(res));
  /* read the whole input */
  Buffer input; memset(&input, 0, sizeof(input));
  uint8_t readbuf[8192];
  while (true) {
    errno = 0;
    size_t n = fread(readbuf, 1, sizeof(readbuf), in);
    if (n) { if (!BufferAppend(&input, readbuf, n)) { BufferFree(&input); res.fail_kind = 5; return res; } }
    if (n == 0) {
      if (ferror(in)) {
        int e = errno;
        fprintf(stderr, "failed to read input [%s]: %s\n", in_display, strerror(e ? e : EIO));
        BufferFree(&input); res.fail_kind = 5; return res;
      }
      break;
    }
    if (n < sizeof(readbuf)) {
      if (ferror(in)) {
        int e = errno;
        fprintf(stderr, "failed to read input [%s]: %s\n", in_display, strerror(e ? e : EIO));
        BufferFree(&input); res.fail_kind = 5; return res;
      }
      if (feof(in)) break;
    }
  }
  res.in_size = input.len;

  /* comment check based on the first stream */
  if (g_comment_len > 0) {
    int check = CheckFirstMetadata(input.data, input.len);
    if (check == 3) {
      res.fail_kind = 4;
      BufferFree(&input);
      return res;
    } else if (check == 1) {
      res.comment_absent = true;
    }
  }

  Buffer current; memset(&current, 0, sizeof(current));
  if (!BufferAppend(&current, input.data, input.len)) { BufferFree(&input); res.fail_kind = 5; return res; }
  BufferFree(&input);

  bool first = true;
  while (true) {
    if (current.len == 0 && !first) break;
    FILE *spool = NULL;
    if (g_mode != MODE_TEST) {
      spool = tmpfile();
      if (!spool) { BufferFree(&current); res.fail_kind = 5; return res; }
    }
    OneStreamResult one;
    Buffer synthetic; memset(&synthetic, 0, sizeof(synthetic));
    const uint8_t *decode_data = current.data;
    size_t decode_len = current.len;
    bool used_synthetic = false;
    uint64_t skip = 0;
    if (g_dictionary_len > 0 && current.len > 0) {
      synthetic = BuildSynthetic(current.data, current.len);
      if (synthetic.data) {
        decode_data = synthetic.data; decode_len = synthetic.len; used_synthetic = true; skip = g_dictionary_len;
      }
    }
    one = DecodeOne(decode_data, decode_len, spool, skip);
    if (one.status != 0) {
      if (spool) fclose(spool);
      BufferFree(&synthetic);
      BufferFree(&current);
      if (one.status == 2) res.fail_kind = 2;
      else { res.fail_kind = 1; res.error_code = one.error_code; }
      return res;
    }
    res.out_size += one.produced;
    /* figure leftover */
    const uint8_t *leftover_ptr = NULL;
    size_t leftover_len = 0;
    if (used_synthetic) {
      /* one.consumed is within the synthetic buffer; remaining bytes there
         correspond to the following streams. */
      if (one.consumed <= synthetic.len) {
        leftover_ptr = synthetic.data + one.consumed;
        leftover_len = synthetic.len - one.consumed;
      }
    } else {
      if (one.consumed <= current.len) {
        leftover_ptr = current.data + one.consumed;
        leftover_len = current.len - one.consumed;
      }
    }
    /* write this stream's output */
    if (g_mode != MODE_TEST && spool) {
      uint64_t before = 0; (void)before;
      if (!CopySpoolToOutput(spool, out, out_display, NULL)) {
        fclose(spool);
        BufferFree(&synthetic);
        BufferFree(&current);
        res.fail_kind = 5; /* message already printed by WriteOutput */
        res.out_size = res.out_size; /* keep */
        return res;
      }
    }
    if (spool) fclose(spool);

    if (leftover_len == 0) {
      BufferFree(&synthetic);
      BufferFree(&current);
      break;
    }
    /* extra input */
    Buffer next; memset(&next, 0, sizeof(next));
    if (leftover_ptr && leftover_len) (void)BufferAppend(&next, leftover_ptr, leftover_len);
    BufferFree(&synthetic);
    BufferFree(&current);
    current = next;
    if (!g_concat) {
      BufferFree(&current);
      res.fail_kind = 3;
      return res;
    }
    if (g_verbose) fprintf(stderr, "extra input\n");
    first = false;
  }
  res.success = true;
  return res;
}

/* ---------------- per-file processing ---------------- */
static void CopyStat(const char *input_path, const char *output_path) {
  struct stat st;
  if (stat(input_path, &st) != 0) return;
  (void)chmod(output_path, st.st_mode & 0777);
  struct timespec ts[2];
  ts[0] = st.st_atim;
  ts[1] = st.st_mtim;
  (void)utimensat(AT_FDCWD, output_path, ts, 0);
}

#define OUTK_FILE 0
#define OUTK_STDOUT 1
#define OUTK_NONE 2

typedef struct {
  bool is_stdin;
  const char *path; /* NULL for default stdin pseudo-entry */
} Entry;

static int ProcessEntry(Entry entry) {
  clock_t start = clock();
  const char *in_display = entry.is_stdin ? "con" : entry.path;
  int out_kind = OUTK_NONE;
  char *derived_out = NULL;
  const char *out_path = NULL;

  if (g_mode == MODE_TEST) {
    out_kind = OUTK_NONE;
  } else if (g_output_name) {
    out_kind = OUTK_FILE; out_path = g_output_name;
  } else if (g_stdout_set) {
    out_kind = OUTK_STDOUT;
  } else if (entry.is_stdin) {
    out_kind = OUTK_STDOUT;
  } else {
    out_kind = OUTK_FILE;
    if (g_mode == MODE_COMPRESS) {
      size_t a = strlen(entry.path), b = strlen(g_suffix);
      derived_out = (char *)malloc(a + b + 1);
      memcpy(derived_out, entry.path, a); memcpy(derived_out + a, g_suffix, b + 1);
      out_path = derived_out;
    } else {
      size_t plen = strlen(entry.path), slen = strlen(g_suffix);
      if (plen < slen || strcmp(entry.path + plen - slen, g_suffix) != 0) {
        fprintf(stderr, "input file [%s] suffix mismatch\n", entry.path);
        free(derived_out); return 1;
      }
      size_t stripped = plen - slen;
      derived_out = (char *)malloc(stripped + 1);
      memcpy(derived_out, entry.path, stripped); derived_out[stripped] = '\0';
      const char *slash = strrchr(derived_out, '/');
      const char *bslash = strrchr(derived_out, '\\');
      const char *sep = slash;
      if (bslash && (!sep || bslash > sep)) sep = bslash;
      const char *base = sep ? sep + 1 : derived_out;
      if (base[0] == '\0') {
        fprintf(stderr, "empty output file name for [%s] input file\n", entry.path);
        free(derived_out); return 1;
      }
      out_path = derived_out;
    }
  }

  FILE *in_fp = stdin;
  if (!entry.is_stdin) {
    errno = 0;
    in_fp = fopen(entry.path, "rb");
    if (!in_fp) {
      fprintf(stderr, "failed to open input file [%s]: %s\n", entry.path, strerror(errno));
      free(derived_out); return 1;
    }
  }

  /* input size (regular/seekable named files) */
  bool have_size = false; uint64_t file_size = 0;
  if (!entry.is_stdin && in_fp) {
    if (fseek(in_fp, 0, SEEK_END) == 0) {
      long long sz = (long long)ftello(in_fp);
      if (sz >= 0) { have_size = true; file_size = (uint64_t)sz; }
      (void)fseek(in_fp, 0, SEEK_SET);
    } else {
      clearerr(in_fp);
    }
  }

  FILE *out_fp = NULL;
  const char *out_display = "con";
  if (out_kind == OUTK_FILE) {
    out_display = out_path;
    int fd;
    if (g_force_set) fd = open(out_path, O_WRONLY | O_CREAT | O_TRUNC, 0600);
    else fd = open(out_path, O_WRONLY | O_CREAT | O_EXCL, 0600);
    if (fd < 0) {
      fprintf(stderr, "failed to open output file [%s]: %s\n", out_path, strerror(errno));
      if (!entry.is_stdin && in_fp) fclose(in_fp);
      free(derived_out); return 1;
    }
    out_fp = fdopen(fd, "wb");
    if (!out_fp) {
      fprintf(stderr, "failed to open output file [%s]: %s\n", out_path, strerror(errno));
      close(fd);
      if (!entry.is_stdin && in_fp) fclose(in_fp);
      free(derived_out); return 1;
    }
  } else if (out_kind == OUTK_STDOUT) {
    out_fp = stdout; out_display = "con";
  }

  /* terminal checks */
  if (!g_force_set) {
    const char *term_msg = NULL;
    if ((g_mode == MODE_DECOMPRESS || g_mode == MODE_TEST) && entry.is_stdin && isatty(STDIN_FILENO)) {
      term_msg = "Use -h help. Use -f to force input from a terminal.\n";
    } else if (g_mode == MODE_COMPRESS && out_kind == OUTK_STDOUT && isatty(STDOUT_FILENO)) {
      term_msg = "Use -h help. Use -f to force output to a terminal.\n";
    }
    if (term_msg) {
      fprintf(stderr, "%s", term_msg);
      if (!entry.is_stdin && in_fp) fclose(in_fp);
      else if (entry.is_stdin) fclose(in_fp);
      if (out_kind == OUTK_FILE && out_fp) { fclose(out_fp); unlink(out_path); }
      free(derived_out); return 1;
    }
  }

  bool success = false;
  bool comment_absent = false;
  uint64_t in_size = 0, out_size = 0;
  int fail_kind = 0; int error_code = 0;

  if (g_mode == MODE_COMPRESS) {
    CompressResult r = DoCompress(in_fp, out_fp, in_display, out_display, entry.is_stdin, have_size, file_size);
    success = r.success; in_size = r.in_size; out_size = r.out_size;
    if (!success) fail_kind = 5;
  } else {
    DecompressResult r = DoDecompress(in_fp, out_fp, in_display, out_display);
    success = r.success; in_size = r.in_size; out_size = r.out_size;
    comment_absent = r.comment_absent; fail_kind = r.fail_kind; error_code = r.error_code;
  }

  if (!success) {
    if (!(g_mode != MODE_COMPRESS && (fail_kind == 1 || fail_kind == 2 || fail_kind == 3 || fail_kind == 4))) {
      /* DoCompress and some decompress failures already printed a message. */
      if (g_mode != MODE_COMPRESS && fail_kind == 5) {
        /* message already printed */
      }
    }
    if (g_mode != MODE_COMPRESS) {
      if (fail_kind == 1 || fail_kind == 2 || fail_kind == 3 || fail_kind == 4) {
        fprintf(stderr, "corrupt input [%s]\n", in_display);
        if (g_verbose) {
          if (fail_kind == 1) { char rb[128]; fprintf(stderr, "reason: %s\n", DecoderReason(error_code, rb, sizeof(rb))); }
          else if (fail_kind == 2) fprintf(stderr, "reason: truncated input\n");
          else if (fail_kind == 3) fprintf(stderr, "reason: extra input\n");
          else if (fail_kind == 4) fprintf(stderr, "reason: comment mismatch\n");
        }
      }
    }
    /* cleanup */
    fclose(in_fp);
    if (out_kind == OUTK_FILE && out_fp) { fclose(out_fp); unlink(out_path); }
    else if (out_kind == OUTK_STDOUT && out_fp) { /* do not print further */ }
    free(derived_out);
    return 1;
  }

  /* success */
  clock_t finish = clock();
  if (g_verbose) {
    char b1[64], b2[64];
    FormatSize(in_size, b1, sizeof(b1)); FormatSize(out_size, b2, sizeof(b2));
    double elapsed = (double)(finish - start) / (double)CLOCKS_PER_SEC;
    fprintf(stderr, "%s [%s]: %s -> %s in %.2f sec\n",
            g_mode == MODE_COMPRESS ? "Compressed" : "Decompressed",
            in_display, b1, b2, elapsed);
  }
  if (comment_absent) {
    fprintf(stderr, "corrupt input [%s]\n", in_display);
    if (g_verbose) fprintf(stderr, "reason: comment mismatch\n");
  }

  bool squash_removed = false;
  if (g_mode == MODE_COMPRESS && g_squash && out_size > in_size) {
    if (g_verbose) fprintf(stderr, "Output is larger than input\n");
    squash_removed = true;
    if (out_kind == OUTK_FILE) unlink(out_path);
  }

  bool fclose_failed = false;
  if (out_kind != OUTK_NONE && out_fp) {
    errno = 0;
    if (fclose(out_fp) != 0) {
      int e = errno;
      fprintf(stderr, "fclose failed [%s]: %s\n", out_display, strerror(e ? e : EIO));
      fclose_failed = true;
    }
    out_fp = NULL;
  }

  if (!squash_removed) {
    if (out_kind == OUTK_FILE && !entry.is_stdin && !g_no_copy_stat) {
      CopyStat(entry.path, out_path);
    }
    if (g_rm && !entry.is_stdin) {
      unlink(entry.path);
    }
  }

  fclose(in_fp);
  free(derived_out);
  return fclose_failed ? 1 : 0;
}

int main(int argc, char **argv) {
  /* program name / aliases */
  const char *argv0 = (argc > 0 && argv[0]) ? argv[0] : "";
  const char *base = argv0;
  for (const char *p = argv0; *p; p++) {
    if (*p == '/' || *p == '\\') base = p + 1;
  }
  g_prog_name = base;
  {
    /* alias key: basename truncated at first '.' */
    size_t klen = 0; while (base[klen] && base[klen] != '.') klen++;
    if ((klen == 5 && strncmp(base, "brcat", 5) == 0)) {
      g_mode = MODE_DECOMPRESS; g_mode_set = true;
      g_concat = true; g_concat_set = true;
      g_stdout_set = true;
    } else if (klen == 8 && strncmp(base, "unbrotli", 8) == 0) {
      g_mode = MODE_DECOMPRESS; g_mode_set = true;
    }
  }
  g_suffix = DupStr(".br");

  if (!LoadBrotli()) {
    return 1;
  }
  ParseArgs(argc, argv);
  if (!ValidateParams()) return 1;
  if (!LoadDictionary()) return 1;

  if (g_inputs_len == 0) {
    Entry e; e.is_stdin = true; e.path = NULL;
    return ProcessEntry(e);
  }
  for (size_t i = 0; i < g_inputs_len; i++) {
    Entry e;
    e.path = g_inputs[i];
    e.is_stdin = (strcmp(g_inputs[i], "-") == 0);
    int rc = ProcessEntry(e);
    if (rc != 0) return rc;
  }
  return 0;
}
