/* ---------------- dynamic library (system brotli) ---------------- */
typedef void *(*EncCreateFn)(void *, void *, void *);
typedef void (*EncDestroyFn)(void *);
typedef int (*EncSetParamFn)(void *, int, uint32_t);
typedef int (*EncStreamFn)(void *, int, size_t *, const uint8_t **, size_t *, uint8_t **, size_t *);
typedef int (*EncIsFinishedFn)(void *);
typedef int (*EncHasMoreFn)(void *);

