typedef void (*DecDestroyFn)(void *);
typedef int (*DecSetParamFn)(void *, int, uint32_t);
typedef int (*DecStreamFn)(void *, size_t *, const uint8_t **, size_t *, uint8_t **, size_t *);
typedef int (*DecIsFinishedFn)(void *);
typedef int (*DecHasMoreFn)(void *);
typedef int (*DecErrorCodeFn)(void *);
typedef const char *(*DecErrorStringFn)(int);

static EncCreateFn p_EncCreate;
static EncDestroyFn p_EncDestroy;
static EncSetParamFn p_EncSetParam;
static EncStreamFn p_EncStream;
static EncIsFinishedFn p_EncIsFinished;
static EncHasMoreFn p_EncHasMore;
static DecCreateFn p_DecCreate;
