static bool AddInput(char *s) {
  if (g_inputs_len == g_inputs_cap) {
    size_t nc = g_inputs_cap ? g_inputs_cap * 2 : 16;
    char **np = (char **)realloc(g_inputs, nc * sizeof(char *));
    if (!np) return false;
    g_inputs = np; g_inputs_cap = nc;
  }
  g_inputs[g_inputs_len++] = s;
  return true;
}

