static bool ParseFirstBlock(const uint8_t *data, size_t len, FirstBlockInfo *info) {
  memset(info, 0, sizeof(*info));
  size_t wbits = 0; bool large = false;
  if (!ParseWindowBits(data, len, &wbits, &large)) return false;
