  if (!isuncomp) { info->kind = 3; return true; }
  br.bitpos = (br.bitpos + 7) & ~((size_t)7);
  size_t start = br.bitpos / 8;
  size_t mlen = (size_t)mlen_minus + 1;
  if (start > len || mlen > len - start) return false;
  info->kind = 2;
  info->stored_start = start;
  info->stored_len = mlen;
  info->after_block = start + mlen;
  return true;
