    pos += clen;
  }
  return BWAlign(bw);
}

/* Build a synthetic stream: window bits + stored dictionary + original payload.
   Returns an empty Buffer on failure. */
static Buffer BuildSynthetic(const uint8_t *data, size_t len) {
  Buffer out; memset(&out, 0, sizeof(out));
  size_t wbits = 0; bool large = false;
  if (!ParseWindowBits(data, len, &wbits, &large)) return out;
  (void)large;
  FirstBlockInfo info;
  bool have_info = ParseFirstBlock(data, len, &info);
  if (have_info && (info.kind == 1 || info.kind == 2)) {
    BitWriter bw; memset(&bw, 0, sizeof(bw));
    if (!BWAppendWindowAndDict(&bw, data, wbits)) { BufferFree(&bw.buf); return out; }
