  size_t meta_start;
  size_t meta_len;
  size_t after_block; /* byte offset just past a metadata/stored block */
  size_t stored_start;
  size_t stored_len;
} FirstBlockInfo;

static bool ParseFirstBlock(const uint8_t *data, size_t len, FirstBlockInfo *info) {
  memset(info, 0, sizeof(*info));
  size_t wbits = 0; bool large = false;
  if (!ParseWindowBits(data, len, &wbits, &large)) return false;
  (void)large;
  BitReader br; br.data = data; br.len = len; br.bitpos = wbits;
  uint32_t islast;
  if (!BRReadBit(&br, &islast)) return false;
  if (islast) {
    uint32_t empty;
    if (!BRReadBit(&br, &empty)) return false;
    if (empty) { info->kind = 3; return true; }
    info->kind = 3; return true;
  }
  uint32_t mnib;
  if (!BRRead(&br, 2, &mnib)) return false;
  if (mnib == 3) {
    uint32_t reserved;
    if (!BRReadBit(&br, &reserved)) return false;
    uint32_t skipbytes;
    if (!BRRead(&br, 2, &skipbytes)) return false;
    uint64_t meta_len = 0;
    if (skipbytes != 0) {
      uint32_t v = 0;
      if (!BRRead(&br, (int)(8 * skipbytes), &v)) return false;
      meta_len = (uint64_t)v + 1;
    }
    br.bitpos = (br.bitpos + 7) & ~((size_t)7);
    size_t start = br.bitpos / 8;
    if (start > len || meta_len > len - start) return false;
    info->kind = 1;
    info->meta_start = start;
    info->meta_len = (size_t)meta_len;
    info->after_block = start + (size_t)meta_len;
    return true;
  }
  int nibbles = 4 + (int)mnib;
  uint32_t mlen_minus = 0;
  for (int i = 0; i < nibbles; i++) {
    uint32_t nib;
    if (!BRRead(&br, 4, &nib)) return false;
    mlen_minus |= nib << (4 * i);
