    size_t clen = g_dictionary_len - pos;
    if (clen > 1000000) clen = 1000000;
    if (!BWStoredBlock(bw, g_dictionary + pos, clen)) return false;
    pos += clen;
  }
  return BWAlign(bw);
}

/* Build a synthetic stream: window bits + stored dictionary + original payload.
   Returns an empty Buffer on failure. */
static Buffer BuildSynthetic(const uint8_t *data, size_t len) {
  Buffer out; memset(&out, 0, sizeof(out));
  size_t wbits = 0; bool large = false;
  if (!ParseWindowBits(data, len, &wbits, &large)) return out;
  (void)large;
  FirstBlockInfo info;
  bool have_info = ParseFirstBlock(data, len, &info);
  if (have_info && (info.kind == 1 || info.kind == 2)) {
    BitWriter bw; memset(&bw, 0, sizeof(bw));
    if (!BWAppendWindowAndDict(&bw, data, wbits)) { BufferFree(&bw.buf); return out; }
    bool ok;
    if (info.kind == 1) {
      ok = BWMetadataBlock(&bw, data + info.meta_start, info.meta_len);
    } else {
      ok = BWStoredBlock(&bw, data + info.stored_start, info.stored_len);
    }
    if (ok && info.after_block < len) ok = BWAppendBytes(&bw, data + info.after_block, len - info.after_block);
    if (!ok) { BufferFree(&bw.buf); return out; }
    out = bw.buf;
    return out;
  }
  /* generic bit transplant (first block is compressed/other) */
  {
    BitWriter bw; memset(&bw, 0, sizeof(bw));
    if (!BWAppendWindowAndDict(&bw, data, wbits)) { BufferFree(&bw.buf); return out; }
    size_t total_bits = len * 8;
    if (wbits < total_bits) {
      size_t payload_bits = total_bits - wbits;
      size_t payload_bytes = (payload_bits + 7) / 8;
      size_t src_byte = wbits / 8;
      int src_off = (int)(wbits % 8);
      for (size_t i = 0; i < payload_bytes; i++) {
        size_t idx = src_byte + i;
        uint8_t b = 0;
        if (src_off == 0) {
          if (idx < len) b = data[idx];
        } else {
