          b &= (uint8_t)((1u << (payload_bits % 8)) - 1u);
        }
        if (!BufferAppend(&bw.buf, &b, 1)) { BufferFree(&bw.buf); return out; }
        bw.bit_len += 8;
      }
      bw.bit_len = bw.buf.len * 8;
    }
    out = bw.buf;
    return out;
  }
}

