from stream_meta import stream
REF="/tmp/refbin/executable"; MY="/tmp/mybin/executable"
fails=0
for data in [b"hello",b"world data "*100]:
    for meta in [b"x",b"hello",b"\x00"*10,b"A"*200]:
        s=stream(data,comment=meta)
